"""Versioned definitions are owned by code, never generated by the planner."""
import calendar
from types import MappingProxyType
from .contributors import decimal, money

VERSION = 'financial-metrics-v1'
MONTHS = tuple(m.lower() for m in calendar.month_name if m)
MEANINGS = MappingProxyType({
    'income': 'Recorded positive income-category entries excluding transfers; not verified salary.',
    'gross_purchases': 'Absolute sum of negative non-income, non-transfer expense entries.',
    'net_spending': 'Gross purchases minus positive expense credits; transfers excluded.',
    'refund_candidate_amount': 'Positive expense credits excluding transfers; not independently verified refunds.',
    'refund_candidate_count': 'Number of positive expense credits; not verified refunds.',
    'money_kept': 'Recorded income minus net spending; cash-flow surplus, not net-worth growth.',
    'savings_rate': 'Money kept divided by positive recorded income times one hundred; not available without positive income.',
    'income_source_count': 'Distinct normalized income-source groups in the period.',
    'investment_transfer_in': 'Gross investment-account transfer inflows; does not establish origin or ownership.',
    'investment_transfer_out': 'Absolute gross investment-account transfer outflows; does not establish destination or ownership.',
    'investment_net_contributions': 'Investment transfer inflows minus outflows; no inference of internal ownership.',
    'investment_dividend': 'Signed recorded investment dividend distributions for the period.',
    'investment_interest': 'Signed recorded investment interest for the period.',
    'investment_distributions': 'Recorded dividends plus interest, without adding reinvestments again.',
    'investment_fee': 'Absolute recorded investment fees; separate from distributions and market returns.',
    'investment_reinvest': 'Absolute recorded reinvestment activity; not additional investment income.',
    'holdings_count': 'Distinct consolidated securities across the scoped exact-date snapshots.',
    'holdings_value': 'Sum of scoped holdings market values including any cash represented in holdings.',
    'outside_cash': 'Only cash explicitly outside holdings; never add holdings cash a second time.',
    'portfolio_value': 'Holdings market values plus explicitly outside cash; not total personal wealth.',
    'largest_holding_percent': 'Largest consolidated security market value divided by scoped portfolio value times one hundred.',
    'top_five_holdings_percent': 'Sum of largest five consolidated security values divided by scoped portfolio value times one hundred.',
    'transfer_in': 'Positive bank/card transfer entries; investment activity is a separate, potentially overlapping scope.',
    'transfer_out': 'Absolute negative bank/card transfer entries; do not sum with investment activity.',
    'transfer_row_count': 'Number of bank/card transfer ledger entries, not unique transfers.',
    'confirmed_internal_moved_once': 'Confirmed internal matched-pair amount counted once; consult pairing provenance before asserting identity verification.',
    'confirmed_pairs': 'Number of confirmed matched internal pairs; consult provenance.',
    'external_in': 'Only explicitly confirmed external incoming transfers; unresolved records remain unknown.',
    'external_out': 'Only explicitly confirmed external outgoing transfers; unresolved records remain unknown.',
    'unresolved_gross_amount': 'Sum of absolute unmatched transfer entries requiring review.',
    'unresolved_rows': 'Number of unmatched transfer entries requiring review.',
    'unresolved_transfer_rows': 'Number of unmatched transfer entries requiring review; alias of unresolved_rows.',
    'observed_month_count': 'Number of observed comparison months; insufficient to establish long-term persistence.',
    'unrealized_gain': 'Market value minus complete cost basis; lifetime versus basis, not period price appreciation.',
    'net_worth': 'Sum of aligned scoped account balances with debts signed negative; requires all account valuations at the specified date.',
})
GROUPS = MappingProxyType({
    'merchant_purchase_count_': 'Count of negative purchase entries for this normalized merchant group.',
    'income_source_': 'Positive recorded income attributed to this normalized source; not independently verified salary.',
    'refund_source_': 'Positive expense credits from this normalized source; unverified refund candidates.',
    'category_': 'Net expense amount in this category, after positive expense credits and excluding transfers.',
    'merchant_': 'Net expense amount for this normalized merchant group; identity grouping is heuristic.',
})


def definition(metric_id):
    key = metric_id
    period = next((m for m in MONTHS if key.startswith(m + '_')), None)
    if period:
        key = key[len(period) + 1:]
    percent = key.endswith('_percent')
    if key in MEANINGS:
        meaning = MEANINGS[key]
    else:
        base = key.removesuffix('_percent')
        change = base.startswith('change_') or base.endswith('_change')
        base = base.removeprefix('change_').removesuffix('_change')
        meaning = MEANINGS.get(base)
        if meaning is None:
            meaning = next((text for group, text in GROUPS.items() if base.startswith(group) and base[len(group):]), None)
        if meaning is None:
            raise ValueError('Unknown metric ID: ' + metric_id)
        if change:
            meaning = 'Current minus previous period. ' + meaning
        if percent:
            meaning = 'Change divided by positive previous amount times one hundred. ' + meaning
    count = key.endswith(('_count', '_rows', '_pairs')) or key.startswith('merchant_purchase_count_')
    unit = 'count' if count else '%' if percent or key == 'savings_rate' else 'USD'
    return {'version': VERSION, 'meaning': meaning, 'unit': unit,
            'period': period or 'comparison', 'grain': 'scoped aggregate',
            'rounding': 'half-up to two decimal places; counts integers',
            'null': 'unavailable, never zero', 'sign': 'signed amount unless definition explicitly specifies absolute',
            'time': 'inclusive calendar dates supplied in evidence scope'}


def build_evidence(metric_values, *, definition_version=VERSION, scope=None, data_version='unknown'):
    if definition_version != VERSION:
        raise ValueError('Metric definition version mismatch')
    metrics = {}
    for key, value in metric_values.items():
        spec = definition(key)
        parsed = None if value is None else decimal(value)
        if parsed is not None and spec['unit'] == 'count' and parsed != parsed.to_integral_value():
            raise ValueError('Fractional count')
        formatted = None if parsed is None else str(int(parsed)) if spec['unit'] == 'count' else money(parsed)
        metrics[key] = {'value': formatted, 'definition': spec}
    return {'definition_version': VERSION, 'scope': scope or {}, 'data_version': data_version, 'metrics': metrics}
